if (msg.payload !== '' && typeof global.get('describe.hmi["' + msg.payload + '"]', 'memoryOnly') === 'string') {
    msg.tab = msg.payload;
    msg.name = global.get('describe.hmi["' + msg.payload + '"]', 'memoryOnly');
    msg.payload = 'change';

    return msg;
}

return;

// on unwanted state, stop here
if (msg.payload.match((new RegExp('^(connect|change|lost)$'))) === null) {
    return;
}

// on connect or lost connection, go to auth page
if (msg.payload === 'connect' || msg.payload === 'lost') {
    msg.payload = global.get('describe.app.hmi', 'memoryOnly');;

    return [null, msg];
}

// ui main
msg.version = global.get('describe.app.version', 'memoryOnly');
msg.title = global.get('describe.app.title', 'memoryOnly');
msg.full = msg.title + ' v' + msg.version;
msg.git = "https://github.com/dknr-domotic/" + global.get('describe.app.git', 'memoryOnly');
msg.lang = 'FR-fr';

// ui menu
msg.menus = {};
msg.titles = {};
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};
let s =0;
let pages = global.get('describe.hmi', 'memoryOnly') || {};
for (const tab in pages) {
    msg.menus[tab] = true;
    msg.titles[tab] = pages[tab];
    msg.payload.pages.show[s++] = tab;

    if (tab === msg.tab) {
        msg.title = msg.title + ' - ' + pages[tab];
    }
}

return [msg, null];

msg.payload.project = 'dknr-verisure';

msg.payload.hmi = {
    'detail': 'Alarme',
    'add': 'Compte',
    'mqtt': 'Configurer'
};

// Verisure France cloud API (same API as My Verisure application)
msg.payload.api = {
    'url': 'https://customers.securitasdirect.fr/owa-api/graphql',
    'country': 'FR',
    'lang': 'fr',
    'callby': 'OWA_10',
    'prefix': 'OWA_______________',
    'agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.5005.124 Safari/537.36 Edg/102.0.1245.41',
    'device': {
        'brand': 'samsung',
        'name': 'SM-S901U',
        'os': '12',
        'version': '10.102.0'
    },
    // GraphQL queries by operation name
    'query': {
        'mkLoginToken': 'mutation mkLoginToken($user: String!, $password: String!, $id: String!, $country: String!, $lang: String!, $callby: String!, $idDevice: String!, $idDeviceIndigitall: String!, $deviceType: String!, $deviceVersion: String!, $deviceResolution: String!, $deviceName: String!, $deviceBrand: String!, $deviceOsVersion: String!, $uuid: String!) { xSLoginToken(user: $user, password: $password, country: $country, lang: $lang, callby: $callby, id: $id, idDevice: $idDevice, idDeviceIndigitall: $idDeviceIndigitall, deviceType: $deviceType, deviceVersion: $deviceVersion, deviceResolution: $deviceResolution, deviceName: $deviceName, deviceBrand: $deviceBrand, deviceOsVersion: $deviceOsVersion, uuid: $uuid) { __typename res msg hash refreshToken legals changePassword needDeviceAuthorization mainUser } }',
        'RefreshLogin': 'mutation RefreshLogin($refreshToken: String!, $id: String!, $country: String!, $lang: String!, $callby: String!, $idDevice: String!, $idDeviceIndigitall: String!, $deviceType: String!, $deviceVersion: String!, $deviceResolution: String!, $deviceName: String!, $deviceBrand: String!, $deviceOsVersion: String!, $uuid: String!) {
  xSRefreshLogin(refreshToken: $refreshToken, id: $id, country: $country, lang: $lang, callby: $callby, idDevice: $idDevice, idDeviceIndigitall: $idDeviceIndigitall, deviceType: $deviceType, deviceVersion: $deviceVersion, deviceResolution: $deviceResolution, deviceName: $deviceName, deviceBrand: $deviceBrand, deviceOsVersion: $deviceOsVersion, uuid: $uuid) {
    __typename
    res
