    refreshToken
    legals
    changePassword
    needDeviceAuthorization
    mainUser
  }
}',
        'mkValidateDevice': 'mutation mkValidateDevice($idDevice: String, $idDeviceIndigitall: String, $uuid: String, $deviceName: String, $deviceBrand: String, $deviceOsVersion: String, $deviceVersion: String) {
  xSValidateDevice(idDevice: $idDevice, idDeviceIndigitall: $idDeviceIndigitall, uuid: $uuid, deviceName: $deviceName, deviceBrand: $deviceBrand, deviceOsVersion: $deviceOsVersion, deviceVersion: $deviceVersion) {
    res
    msg
    hash
    refreshToken
    legals
  }
}
',
        'mkSendOTP': 'mutation mkSendOTP($recordId: Int!, $otpHash: String!) {
  xSSendOtp(recordId: $recordId, otpHash: $otpHash) {
    res
    msg
  }
}
',
        'Logout': 'mutation Logout {
  xSLogout
}
',
        'mkInstallationList': 'query mkInstallationList {
  xSInstallations {
    installations {
      numinst
      alias
      panel
      type
    }
  }
}
',
        'Srv': 'query Srv($numinst: String!, $uuid: String) {
  xSSrv(numinst: $numinst, uuid: $uuid) {
    res
    msg
    language
    installation {
      numinst
      role
      alias
      status
      panel
      sim
      instIbs
      services {
        idService
        active
        visible
        bde
        isPremium
        codOper
        request
        minWrapperVersion
        unprotectActive
        unprotectDeviceStatus
        instDate
        genericConfig {
          total
          attributes {
            key
            value
          }
        }
        attributes {
          attributes {
            name
            value
            active
          }
        }
      }
      configRepoUser {
        alarmPartitions {
          id
          enterStates
          leaveStates
        }
      }
      capabilities
    }
  }
}',
        'Status': 'query Status($numinst: String!) {
  xSStatus(numinst: $numinst) {
    status
    timestampUpdate
    wifiConnected
    exceptions {
      status
      deviceType
      alias
    }
  }
}'
    }
};

msg.payload.enum = {
    // Verisure panel status code
    'state': {
        'D': 'Désarmée',
        'P': 'Partielle jour',
        'Q': 'Partielle nuit',
        'T': 'Totale',
        'E': 'Périmétrique',
        'B': 'Partielle jour et périmétrique',
        'C': 'Partielle nuit et périmétrique',
        'A': 'Totale et périmétrique',
        'X': 'Annexe',
        'R': 'Partielle jour et annexe',
        'S': 'Partielle nuit et annexe',
        'O': 'Totale et annexe'
    }
};

// Translation of options labels (french is the reference language)
msg.payload.translate = {
    'en': {
        'Désarmée': 'Disarmed',
        'Partielle jour': 'Partial day',
        'Partielle nuit': 'Partial night',
        'Totale': 'Total',
        'Périmétrique': 'Perimeter',
        'Partielle jour et périmétrique': 'Partial day and perimeter',
        'Partielle nuit et périmétrique': 'Partial night and perimeter',
        'Totale et périmétrique': 'Total and perimeter',
        'Annexe': 'Annex',
        'Partielle jour et annexe': 'Partial day and annex',
        'Partielle nuit et annexe': 'Partial night and annex',
        'Totale et annexe': 'Total and annex'
    }
};

const e = msg.payload.enum;

// control entry: [name, entity, group, type, unit, default value, options: {key: name}, ha type, ha state_class, ha device_class, device field]
msg.payload.control = {
    'panel': {
        'state': ['Etat', 'state', 'sensor', 'enum', '', 'D', e.state, 'sensor', '', 'enum', 'status'],
        'armed': ['Alarme armée', 'armed', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', '', 'armed'],
        'wifi': ['Wifi connecté', 'wifi', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'connectivity', 'wifi'],
        'timestamp': ['Mise à jour', 'timestamp', 'sensor', 'text', '', '', {}, 'sensor', '', 'timestamp', 'timestamp']
    }
};

return msg;

// Build a Verisure API request
// msg.api: { operation, variables (optional), numinst (optional), otp: { hash, code } (optional) }
// output 1: http request / output 2: invalid request, back to caller

const crypto = global.get('crypto');
const conf = global.get('describe.api', 'memoryOnly') || {};
const account = global.get('account', 'default') || {};
const installations = global.get('installations', 'default') || {};
const caps = flow.get('caps', 'memoryOnly') || {};
const api = msg.api;

if (typeof api !== 'object' || api === null || typeof (conf.query || {})[api.operation] !== 'string' || typeof account.user !== 'string' || account.user === '') {
    msg.result = { 'ok': false, 'status': 0, 'data': {}, 'error': 'Requête invalide', 'code': '', 'detail': {}, 'transient': false, 'waf': false };

    return [null, msg];
}

const op = api.operation;
const dev = conf.device || {};
const now = new Date();

// Request id, same format as the mobile application
const id = conf.prefix + account.user + '_______________'
    + now.getFullYear() + (now.getMonth() + 1) + now.getDate()
    + now.getHours() + now.getMinutes() + (now.getMilliseconds() * 1000);

// One operation id by runtime
let apollo = flow.get('apollo', 'memoryOnly');
if (typeof apollo !== 'string') {
    apollo = crypto.randomBytes(64).toString('hex');
    flow.set('apollo', apollo, 'memoryOnly');
}

let variables = { ...(api.variables || {}) };

if (op === 'mkLoginToken' || op === 'RefreshLogin') {
    variables = {
        ...variables,
        'id': id,
        'country': conf.country,
        'lang': conf.lang,
        'callby': conf.callby,
        'idDevice': account.device,
        'idDeviceIndigitall': account.indigitall,
        'deviceType': '',
        'deviceVersion': dev.version,
        'deviceResolution': '',
        'deviceName': dev.name,
        'deviceBrand': dev.brand,
        'deviceOsVersion': dev.os,
        'uuid': account.uuid
    };
    if (op === 'mkLoginToken') {
        variables.user = account.user;
    }
}

if (op === 'mkValidateDevice') {
    variables = {
        'idDevice': account.device,
        'idDeviceIndigitall': account.indigitall,
        'uuid': account.uuid,
        'deviceName': dev.name,
        'deviceBrand': dev.brand,
        'deviceOsVersion': dev.os,
        'deviceVersion': dev.version
    };
}

let headers = {
    'app': JSON.stringify({ 'appVersion': dev.version, 'origin': 'native' }),
    'User-Agent': conf.agent,
    'content-type': 'application/json; charset=utf-8',
    'X-APOLLO-OPERATION-ID': apollo,
    'X-APOLLO-OPERATION-NAME': op,
    'extension': '{"mode":"full"}'
};

if (typeof api.numinst === 'string' && typeof installations[api.numinst] === 'object') {
    headers.numinst = api.numinst;
    headers.panel = installations[api.numinst].panel || '';
    if (typeof caps[api.numinst] === 'object' && typeof caps[api.numinst].token === 'string') {
        headers['X-Capabilities'] = caps[api.numinst].token;
    }
}

let auth = {
    'loginTimestamp': account.loginTimestamp || 0,
    'user': account.user,
    'id': id,
    'country': conf.country,
    'lang': conf.lang,
    'callby': conf.callby
};

if (['mkValidateDevice', 'RefreshLogin', 'mkSendOTP'].includes(op)) {
    auth.hash = '';
    auth.refreshToken = '';
    headers.auth = JSON.stringify(auth);
} else if (op !== 'mkLoginToken' && typeof account.hash === 'string' && account.hash !== '') {
    auth.hash = account.hash;
    headers.auth = JSON.stringify(auth);
}

if (typeof api.otp === 'object' && api.otp !== null) {
    headers.security = JSON.stringify({ 'token': api.otp.code, 'type': 'OTP', 'otpHash': api.otp.hash });
}

msg.url = env.get('DKNR_VERISURE_URL') || conf.url;
msg.headers = headers;
msg.requestTimeout = 30000;
msg.payload = { 'operationName': op, 'variables': variables, 'query': conf.query[op] };
if (Object.keys(variables).length === 0 && op === 'mkInstallationList') {
    delete msg.payload.variables;
}

node.status({ fill: 'blue', shape: 'ring', text: op });

return [msg, null];

// Normalize a Verisure API response then go back to caller
// msg.result: { ok, status, data, error, code, detail, transient, waf }

const api = msg.api || {};

let raw = msg.payload;
if (Buffer.isBuffer(raw)) {
    raw = raw.toString();
}

let body = raw;
if (typeof raw === 'string') {
    try {
        body = JSON.parse(raw);
    } catch (e) {
        body = null;
    }
}

let result = {
    'ok': false,
    'status': msg.statusCode,
    'data': {},
    'error': '',
    'code': '',
    'detail': {},
    'transient': false,
    'waf': false
};

if (typeof msg.statusCode !== 'number') {
    result.error = 'Verisure injoignable';
    result.transient = true;
} else if (msg.statusCode === 403 && typeof raw === 'string' && raw.includes('_Incapsula_Resource')) {
    result.error = 'Accès temporairement bloqué par Verisure (trop de requêtes)';
    result.transient = true;
    result.waf = true;
} else if (typeof body !== 'object' || body === null) {
    result.error = 'Réponse invalide (HTTP ' + msg.statusCode + ')';
    result.transient = true;
} else {
    if (typeof body.data === 'object' && body.data !== null) {
        result.data = body.data;
    }
    if (Array.isArray(body.errors) && body.errors.length > 0) {
        const first = body.errors[0] || {};
        const data = typeof first.data === 'object' && first.data !== null ? first.data : {};
        result.code = data.err !== undefined && data.err !== null ? String(data.err) : '';
        result.error = String(first.message || 'Erreur') + (result.code !== '' ? ' [' + result.code + ']' : '');
        result.detail = data;
        // Verisure own fault, not a verdict
        result.transient = first.name === 'TimeoutError' || data.err === 'TimeoutError' || Number(data.status) >= 500;
    } else if (msg.statusCode >= 400) {
        result.error = 'HTTP ' + msg.statusCode;
        result.transient = msg.statusCode >= 500 || msg.statusCode === 403;
    } else {
        result.ok = true;
    }
}

msg.result = result;

// Last answer, shown in account page
flow.set('api_last', {
    'operation': api.operation,
    'status': result.status,
    'error': result.error,
    'at': Date.now()
}, 'memoryOnly');

// Do not keep secrets in message
delete msg.headers;
delete msg.url;
delete msg.requestTimeout;
delete msg.responseUrl;
delete msg.redirectList;
delete msg.retry;
delete api.variables;
delete api.otp;
msg.payload = '';

if (result.ok) {
    node.status({ fill: 'green', shape: 'dot', text: api.operation });
} else {
    node.status({ fill: 'red', shape: 'ring', text: api.operation + ' : ' + result.error });
}

return msg;

// Check session before reading the alarm (cloud API, no local access)
// msg.force: read now (still one read by 20 seconds)
// output 1: session valid / output 2: session renewal request

const account = global.get('account', 'default') || {};

if (account.status !== 'ok') {
    node.status({ fill: 'grey', shape: 'ring', text: 'pas de compte connecté' });

    return;
}

const now = Date.now();
const interval = Math.max(60, Number(global.get('mqtt.interval', 'default')) || 180) * 1000;
const last = flow.get('last_poll', 'memoryOnly') || 0;
const busy = flow.get('busy', 'memoryOnly') || 0;
const pause = flow.get('pause', 'memoryOnly') || 0;

// previous read not finished, or Verisure asked to slow down
if (now - busy < 90000 || now < pause) {

    return;
}

if (now - last < (msg.force === true ? 20000 : interval)) {

    return;
}

flow.set('busy', now, 'memoryOnly');
flow.set('last_poll', now, 'memoryOnly');

if (typeof account.hash === 'string' && account.hash !== '' && (account.exp || 0) - now > 60000) {
    node.status({ fill: 'green', shape: 'dot', text: 'session valide' });

    return [{ 'payload': '' }, null];
}

node.status({ fill: 'blue', shape: 'ring', text: 'renouvellement de la session' });

return [null, { 'api': { 'operation': 'RefreshLogin', 'variables': { 'refreshToken': account.refreshToken || '' } } }];

// Session renewal response
// output 1: session valid / output 2: notification (limited) / output 3: refresh UI / output 4: notification

// Read expiration of a token (ms), 5 minutes if unknown
function expire(token) {
    try {
        const claims = JSON.parse(Buffer.from(String(token).split('.')[1], 'base64').toString());
        if (typeof claims.exp === 'number') {

            return claims.exp * 1000;
        }
    } catch (e) { }

    return Date.now() + 300000;
}

// Save session tokens (refresh token changes at each renewal)
function store(account, data) {
    account.hash = data.hash;
    if (typeof data.refreshToken === 'string' && data.refreshToken !== '') {
        account.refreshToken = data.refreshToken;
    }
    account.exp = expire(data.hash);
    account.loginTimestamp = Date.now();
    account.status = 'ok';
    global.set('account', account, 'default');
}

const r = msg.result || {};
const data = (r.data || {}).xSRefreshLogin || {};
const account = global.get('account', 'default') || {};

if (r.ok === true && data.res === 'OK' && typeof data.hash === 'string' && data.hash !== '') {
    store(account, data);
    node.status({ fill: 'green', shape: 'dot', text: 'session renouvelée' });

    return [{ 'payload': '' }, null, null, null];
}

flow.set('busy', 0, 'memoryOnly');

if (r.waf === true) {
    flow.set('pause', Date.now() + 900000, 'memoryOnly');
}

// Session refused by Verisure: never retry alone, the user must login again
if (r.transient !== true && (['60067', '60052'].includes(r.code) || (account.refreshToken || '') === '')) {
    account.status = 'reauth';
    account.hash = '';
    account.refreshToken = '';
    global.set('account', account, 'default');
    node.status({ fill: 'red', shape: 'ring', text: 'session expirée' });

    return [null, null, { 'payload': '' }, { 'payload': 'Session Verisure expirée : reconnectez-vous depuis la page Compte' }];
}

node.status({ fill: 'red', shape: 'ring', text: r.error || 'erreur' });

return [null, { 'payload': 'Verisure : renouvellement de la session impossible (' + (r.error || 'réponse inattendue') + ')' }, null, null];

// Prepare one read by installation
// output 1: services request (capabilities) / output 2: status request / output 3: installations request

const account = global.get('account', 'default') || {};
const installations = global.get('installations', 'default') || {};
const caps = flow.get('caps', 'memoryOnly') || {};
const ids = Object.keys(installations);
const now = Date.now();

if (ids.length === 0) {

    return [null, null, { 'api': { 'operation': 'mkInstallationList' } }];
}

for (const id of ids) {
    if (typeof caps[id] !== 'object' || (caps[id].exp || 0) - now < 60000) {
        node.send([{ 'topic': id, 'api': { 'operation': 'Srv', 'numinst': id, 'variables': { 'numinst': id, 'uuid': account.uuid } } }, null, null]);
    } else {
        node.send([null, { 'topic': id, 'api': { 'operation': 'Status', 'numinst': id, 'variables': { 'numinst': id } } }, null]);
    }
}

return;

// Services response, keep capabilities of the installation
// output 1: status request / output 2: notification

// Read expiration of a token (ms), 5 minutes if unknown
function expire(token) {
    try {
        const claims = JSON.parse(Buffer.from(String(token).split('.')[1], 'base64').toString());
        if (typeof claims.exp === 'number') {

            return claims.exp * 1000;
        }
    } catch (e) { }

    return Date.now() + 300000;
}

// Save session tokens (refresh token changes at each renewal)
function store(account, data) {
