    flow.set('otp', null, 'memoryOnly');
    store(account, data);

    flow.set('login_password', null, 'memoryOnly');

    return [{ 'api': { 'operation': 'mkInstallationList' } }, null, null, null];
}

// Device validated without session: Verisure waits for a new login from this device
if (r.ok === true && (r.data || {}).xSValidateDevice !== undefined && (r.data || {}).xSValidateDevice !== null) {
    const password = flow.get('login_password', 'memoryOnly');
    flow.set('otp', null, 'memoryOnly');

    if (typeof password === 'object' && password !== null && Date.now() - password.at < 900000) {
        account.status = 'login';
        global.set('account', account, 'default');

        return [null, null, null, { 'api': { 'operation': 'mkLoginToken', 'variables': { 'password': password.value } } }];
    }

    account.status = '';
    global.set('account', account, 'default');
    flow.set('login_password', null, 'memoryOnly');

    return [null, { 'payload': 'Appareil validé par Verisure : reconnectez-vous pour terminer' }, { 'payload': '' }, null];
}

// Verisure asks for a code sent by SMS
if (typeof detail['auth-otp-hash'] === 'string' || Array.isArray(detail['auth-phones'])) {
    let phones = [];
    for (const item of (detail['auth-phones'] || [])) {
        if (typeof item === 'object' && item !== null && item.id !== undefined) {
            phones.push({ 'id': Number(item.id), 'phone': String(item.phone || item.id) });
        }
    }

    flow.set('otp', {
        'hash': detail['auth-otp-hash'] || '',
        'phones': phones,
        'phone': phones.length === 1 ? phones[0].id : '',
        'sent': false
    }, 'memoryOnly');

    account.status = 'otp';
    global.set('account', account, 'default');

    return [null, {
        'payload': msg.step === 'code' ? 'Code refusé : demandez un nouveau SMS' : 'Validation par SMS requise'
    }, { 'payload': '' }, null];
}

account.status = '';
global.set('account', account, 'default');
flow.set('otp', null, 'memoryOnly');
flow.set('login_password', null, 'memoryOnly');

return [null, { 'payload': 'Validation impossible : ' + (r.error || 'réponse inattendue') }, { 'payload': '' }, null];

// Installations list response
// output 1: refresh UI and read alarm / output 2: notification

const r = msg.result || {};
const list = ((r.data || {}).xSInstallations || {}).installations;

flow.set('busy', 0, 'memoryOnly');

if (r.ok !== true || !Array.isArray(list)) {

    return [{ 'payload': '' }, { 'payload': 'Lecture des installations impossible : ' + (r.error || 'réponse inattendue') }];
}

let installations = {};
for (const item of list) {
    if (typeof item !== 'object' || item === null || item.numinst === undefined || item.numinst === null) {

        continue;
    }

    const id = String(item.numinst);
    installations[id] = {
        'numinst': id,
        'alias': String(item.alias || id),
        'panel': String(item.panel || ''),
        'type': String(item.type || '')
    };
}

global.set('installations', installations, 'default');
flow.set('last_poll', 0, 'memoryOnly');

return [{ 'payload': '', 'force': true }, { 'payload': 'Connecté à Verisure : ' + Object.keys(installations).length + ' installation(s)' }];

// Disconnect account
// output 1: logout request / output 2: no session, clean only

const account = global.get('account', 'default') || {};

if (typeof account.user !== 'string' || account.user === '') {

    return;
}

if (typeof account.hash === 'string' && account.hash !== '') {

    return [{ 'api': { 'operation': 'Logout' } }, null];
}

return [null, { 'payload': '' }];

// Forget account, installations and their MQTT topics
// output 1: refresh UI / output 2: notification / output 3: MQTT cleanup

const describe = global.get('describe', 'memoryOnly') || {};
const installations = global.get('installations', 'default') || {};
const topic = global.get('mqtt.topic', 'default') || '';
const discovery = global.get('mqtt.homeassistant', 'default') || '';
const source = 'verisure';
const control = (describe.control || {}).panel || {};

for (const id in installations) {
    // remove retained messages
    for (const k in control) {
        const key = control[k][1];
        if (topic !== '') {
            node.send([null, null, { 'topic': [topic, 'discovery', source, id, key].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
            node.send([null, null, { 'topic': [topic, 'get', source, id, key].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
        }
        if (discovery !== '') {
            node.send([null, null, { 'topic': [discovery, control[k][7], source, id + '_' + key, 'config'].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
        }
    }
    if (topic !== '') {
        node.send([null, null, { 'topic': [topic, 'discovery', source, id].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
    }
}

global.set('account', {}, 'default');
global.set('installations', {}, 'default');
global.set('devices', {}, 'memoryOnly');
flow.set('caps', {}, 'memoryOnly');
flow.set('otp', null, 'memoryOnly');
flow.set('login_password', null, 'memoryOnly');
flow.set('api_last', null, 'memoryOnly');
flow.set('last', {}, 'memoryOnly');
flow.set('busy', 0, 'memoryOnly');
flow.set('login_busy', 0, 'memoryOnly');

return [{ 'payload': '' }, { 'payload': 'Compte Verisure déconnecté' }, null];
